const $=s=>document.querySelector(s);const $$=s=>[...document.querySelectorAll(s)];const whatsapp=m=>'https://wa.me/18484487130?text='+encodeURIComponent(m);const key='dr-stevens-enquiry-v1';let catalogue=[];let bag={};let toastTimer;
function toast(message){$('.toast').textContent=message;$('.toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('.toast').classList.remove('visible'),3200)}
function readBag(){try{const value=JSON.parse(localStorage.getItem(key)||'{}');bag=Object.fromEntries(Object.entries(value||{}).filter(([id,n])=>catalogue.some(p=>p.id===id)&&Number.isInteger(n)&&n>=1&&n<=99))}catch{bag={}}}
function saveBag(){try{localStorage.setItem(key,JSON.stringify(bag))}catch{toast('Your bag is available in this tab, but could not be saved on this device.')}updateCount();renderCart()}
function updateCount(){const count=Object.values(bag).reduce((a,b)=>a+b,0);$$('[data-cart-count]').forEach(el=>el.textContent=count);$('.cart-link').setAttribute('aria-label',`View shopping bag, ${count} item${count===1?'':'s'}`)}
function add(id,qty){if(!catalogue.some(p=>p.id===id)||!Number.isInteger(qty)||qty<1||qty>99)throw new Error('Choose a valid herb and a quantity from 1 to 99.');bag[id]=Math.min(99,(bag[id]||0)+qty);saveBag();toast('Added to your bag. Review it when you’re ready.');return {id,quantity:bag[id],totalItems:Object.values(bag).reduce((a,b)=>a+b,0)}}
$('.menu-toggle').addEventListener('click',()=>{const open=$('#navigation').classList.toggle('open');$('.menu-toggle').setAttribute('aria-expanded',String(open));$('.menu-toggle').setAttribute('aria-label',open?'Close navigation':'Open navigation')});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#navigation').classList.contains('open')){$('#navigation').classList.remove('open');$('.menu-toggle').setAttribute('aria-expanded','false');$('.menu-toggle').setAttribute('aria-label','Open navigation');$('.menu-toggle').focus()}});$$('header nav a').forEach(a=>{if(location.pathname.startsWith(a.getAttribute('href')))a.setAttribute('aria-current','page')});
function filter(){const query=$('#search').value.trim().toLowerCase(),type=$('#type').value,category=$('#category').value,topic=$('#topic').value;let cards=$$('#catalogue .product-card');if($('#sort').value!=='featured')cards.sort((a,b)=>a.dataset.name.localeCompare(b.dataset.name)*($('#sort').value==='za'?-1:1));else cards.sort((a,b)=>catalogue.findIndex(p=>p.id===a.querySelector('[data-add]').dataset.add)-catalogue.findIndex(p=>p.id===b.querySelector('[data-add]').dataset.add));let count=0;cards.forEach(el=>{const hay=((el.dataset.name||'')+' '+(el.dataset.type||'')+' '+(el.dataset.category||'')+' '+(el.dataset.tag||'')+' '+(el.dataset.ailments||'')).toLowerCase();const matches=(!query||query.split(/\s+/).every(w=>hay.includes(w)))&&(!type||el.dataset.type===type||(el.dataset.type&&el.dataset.type.toLowerCase().includes(type.toLowerCase())))&&(!category||el.dataset.category===category||(el.dataset.category&&el.dataset.category.toLowerCase().includes(category.toLowerCase())));el.hidden=!matches;if(matches)count++;$('#catalogue').append(el)});$('#results-count').textContent=`${count} herb${count===1?'':'s'}`;$('#no-results').hidden=count>0;if(!count){const originalQuery=$('#search').value.trim().slice(0,120);$('#missing-description').textContent=originalQuery?'We couldn’t find “'+originalQuery+'” with these filters. Ask Dr Stevens about availability or a suitable next step.':'No herbs match these filters. Dr Stevens can help you explore what’s available.';$('#ask-missing-herb').href=whatsapp('Hello Dr Stevens, I couldn’t find what I was looking for on the website.'+(originalQuery?' I searched for: '+originalQuery+'.':'')+(type?' Preferred format: '+type+'.':'')+(category?' Category: '+category+'.':'')+' Could we discuss availability and what might be suitable?');}const note=$('#topic-guidance');note.hidden=!topic;note.replaceChildren();if(topic){const strong=document.createElement('strong');strong.textContent='Questions about '+topic.toLowerCase()+'?';const p=document.createElement('p');p.textContent='Discuss this health topic with Dr Stevens. The herbs below show all available listings; ask Dr Stevens for product details before choosing.';const a=document.createElement('a');a.href='/health-topics/'+topic.toLowerCase().replace(/[’']/g,'').replace(/[^a-z0-9]+/g,'-').replace(/-$/,'')+'/';a.className='text-link';a.textContent='Explore this health topic ↗';note.append(strong,p,a)}const params=new URLSearchParams();for(const [k,v]of Object.entries({q:query,type,category,topic,sort:$('#sort').value}))if(v&&v!=='featured')params.set(k,v);history.replaceState(null,'',location.pathname+(params.size?'?'+params:''))}
function resetFilters(){['search','type','category','topic'].forEach(id=>$('#'+id).value='');$('#sort').value='featured';filter()}
if($('#catalogue')){const params=new URLSearchParams(location.search);for(const [id,key] of [['search','q'],['type','type'],['category','category'],['topic','topic'],['sort','sort']]){if(params.has(key))$('#'+id).value=params.get(key)}if(!$('#sort').value)$('#sort').value='featured';['search','type','category','topic','sort'].forEach(id=>$('#'+id).addEventListener(id==='search'?'input':'change',filter));$('#reset-filters').addEventListener('click',resetFilters);$('[data-reset]').addEventListener('click',resetFilters);filter()}
$$('[data-add]').forEach(b=>{b.disabled=true;b.addEventListener('click',()=>{const input=b.closest('.button-row')?$('#product-quantity'):null;if(input&&!input.reportValidity())return;try{add(b.dataset.add,input?Number(input.value):1);const original=b.innerHTML;b.innerHTML='✓ Added';setTimeout(()=>{b.innerHTML=original},1400)}catch(e){toast(e.message)}})});
const form=$('#consultation-form');if(form){form.addEventListener('submit',e=>{e.preventDefault();if(!form.reportValidity())return;const name=$('#name').value.trim();const text=`Hello Dr Stevens Herbs,${name?' my name is '+name+'.':''}\nI’m getting in touch about: ${$('#reason').value}.\n${$('#message').value.trim()}\nI would like a free consultation. Please let me know the next steps and availability.`;$('#preview-text').textContent=text;$('#send-message').href=whatsapp(text);$('#message-preview').hidden=false;$('#send-message').focus()});form.addEventListener('input',()=>$('#message-preview').hidden=true)}
function renderCart(){window.renderShoppingBag?.()}
fetch('/assets/catalogue.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(data=>{catalogue=data;readBag();updateCount();$$('[data-add]').forEach(b=>b.disabled=false);renderCart();if($('#catalogue'))filter();if(document.modelContext?.registerTool){const lifecycle=new AbortController();for(const tool of [{name:'read_herb_collections',description:'Read herb categories for discussion with Dr Stevens. Exact products and pricing are agreed directly.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({collections:catalogue})},{name:'stage_enquiry_bag_item',description:'Add a herb collection to the local enquiry bag. Does not place an order or send a message.',inputSchema:{type:'object',properties:{id:{type:'string'},quantity:{type:'integer',minimum:1,maximum:99}},required:['id','quantity'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>add(input?.id,input?.quantity)}])try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}}).catch(()=>{if($('#checkout-content'))$('#checkout-content').innerHTML='<div class="note"><h2>Your checkout could not load.</h2><p>Please refresh to try again. Your bag has not been cleared.</p></div>';if($('#cart-items'))$('#cart-items').innerHTML='<div class="note"><h2>Your bag could not load.</h2><p>Please refresh the page or <a href="https://wa.me/18484487130">contact us directly on WhatsApp</a>.</p></div>';toast('Some collection information could not load. Please refresh to try again.')});addEventListener('storage',e=>{if(e.key===key){readBag();updateCount();renderCart()}});



// A stable outer shell keeps the page in place as the navigation compacts.
const navShell=document.querySelector('.header-shell');if(navShell&&!document.body.classList.contains('checkout-page')){let scheduled=false;const updateNavigation=()=>{navShell.classList.toggle('is-compact',scrollY>140);scheduled=false};addEventListener('scroll',()=>{if(!scheduled){scheduled=true;requestAnimationFrame(updateNavigation)}},{passive:true});updateNavigation()}
